mapper.select:
select ifnull(sum(wh.hours), 0)
from work_hour wh
where wh.work_date between #{begin} and #{end}
  and wh.status = #{status}

select ifnull(sum(wh.hours * p.hourly_wage), 0)
from work_hour wh
left join position p on p.id = wh.position_id
where wh.work_date between #{begin} and #{end}
  and wh.status = #{status}

select ifnull(sum(hours), 0)
from work_hour
where work_date = #{date}
  and status = #{status}
